    "type": "multiple",
    "stem": "在AI生成内容越发便利的今天，眼见未必为实已经成了一种新的共识。随着生成式AI的日益普及，越来越多的公众人物站出来，表示自己被AI冒充了。面对这一迫切的技术失序难题，监管层面的制度供给正在加速跟进。近期，中央网信办全面部署推进规范短视频内容标注工作，明确要求将内容标注设为短视频发布必经环节。人类加大对生成式AI的监管表明（）",
