    "stem": "实践证明，中国特色解决民族问题的道路是完全正确的。这条道路正确把握维护国家统一和实行民族区域自治的关系，坚持统一和自治相结合、民族因素和区域因素相结合，推动中华民族成为认同度更高、凝聚力更强的命运共同体。中华民族缔造统一的多民族国家的内生动力是",
