    "stem": "在资本主义商品生产条件下，每个资本家总是力图不断改进技术，改善经营管理，提高劳动生产率，使其生产的商品的个别劳动时间少于社会必要劳动时间，个别价值低于社会价值，从而获得超额剩余价值。由此可见，单个资本家改进技术、改善管理的主观动机是追求超额剩余价值，但其客观后果则是（）",
