    "answer": "ABD",
    "analysis": "选A、B、D。物质资料的生产方式是生产力和生产关系的统一，农耕时代铁质农具对应小农经济，工业时代机器大生产对应新生产关系。生产方式是社会历史发展的决定力量，从农耕到工业的演变说明生产方式决定社会面貌。生产力的状况决定生产关系的性质与发展变革，铁质农具决定小农经济，机器大生产决定新生产关系。\n钩子：生产方式＝生产力+生产关系统一；生产方式＝社会历史发展决定力量；生产力决定生产关系，但不会“自发”变革。\nC错在{{生产力的发展必然会自发带来生产关系的}}：范围/程度错。生产力的发展不会自动、自发促成生产关系变革，生产关系变革需要通过社会历史实践、社会运动才能实现。"
