    "number": 33,
    "type": "multiple",
    "stem": "马克思在《政治经济学批判(1857—1858年手稿)》中指出:“价值、货币、流通等等，价格等等，还有劳动等等也一样，都是前提。但是我们研究的既不是资本的某一特殊形式，也不是与其他各单个资本相区别的某一单个资本，等等。我们研究的是资本的产生过程……资本一般，这是每一种资本作为资本所共有的规定，或者说是使任何一定量的价值成为资本的那些规定的总和。”马克思关于“资本一般”的理论表明（）",
