    "stem": "(2012-19)人们往往将汉语中的“价”“值”二字与金银财宝等联系起来，而这两字的偏旁却都是“人”,示意价值在“人”。马克思劳动价值论透过商品交换的物与物的关系，揭示了商品价值的科学内涵。其主要观点有",
