    "stem": "以毛泽东同志为主要代表的中国共产党人，在探索社会主义建设道路的过程中，提出了调动一切积极因素为社会主义事业服务、正确认识和处理社会主义社会矛盾的思想、走中国工业化道路的思想，同时还对社会主义发展阶段、“四个现代化”战略目标，以及科学教育文化工作、国防建设、祖国统一和外交工作等提出了重要思想理论观点。党在探索社会主义建设道路过程中取得的重要理论成果()",
