    "stem": "人类命运共同体，顾名思义，就是每个民族、每个国家的前途命运都紧紧联系在一起，应该风雨同舟、荣辱与共，努力把我们生于斯、长于斯的这个星球建成一个和睦的大家庭，把世界各国人民对美好生活的向往变成现实。十几年来的实践证明，人类命运共同体理念反映了世界人民的普遍诉求，代表了人类社会发展进步的正确方向。社会进步作为对社会前进发展的总概括，主要表现在",
