    "number": 144,
    "type": "single",
    "stem": "(2023-1)习近平总书记在为《复兴文库》所写的序言中指出:“修史立典，存史启智，以文化人，这是中华民族延续几千年的一个传统。”“编纂出版《复兴文库》大型历史文献丛书，就是要通过对近代以来重要思想文献的选编，述录先人的开拓，启迪来者的奋斗。”“历史是最好的教科书，一切向前走，都不能忘记走过的路;走得再远、走到再光辉的未来，也不能忘记走过的过去。”这表明",
