    "type": "single",
    "stem": "2026年9月1日上午，国家主席习近平在比什凯克出席上海合作组织成员国元首理事会第二十六次会议。习近平发表题为《推动上海合作组织实现更高质量发展》的重要讲话。习近平指出，今年是上海合作组织成立25周年。25年前，面对冷战的深刻教训、“三股势力”的现实威胁和各国人民对和平与发展的热切期盼，维护主权、安全、发展利益成为地区国家普遍共识。上海合作组织因此应运而生，并日益显示出强大生机活力。25年来，上海合作组织走过不平凡历程。最重大的发展成就是()",
