    "stem": "2026年4月，习近平总书记就服务业发展作出重要指示指出，党的十八大以来，我国服务业规模稳步扩大，质效持续提升，在支撑产业升级、满足民生需要、带动就业扩容等方面发挥了重要作用。2025年，我国服务业增加值首次突破80万亿元，占国内生产总值比重达57.7%，对经济增长的贡献率达61.4%；截至2025年底，服务业就业人数近3.6亿，居三次产业首位。国务院印发的意见明确，要提高现代服务业与先进制造业、现代农业融合发展水平，培育更多服务品牌，到2030年迈上100万亿元台阶。上述情况和部署表明()",
    "options": {
      "A": "服务业是经济增长的主动力",
      "B": "服务业是吸纳就业的主渠道",
      "C": "生产性服务业赋能产业升级",
      "D": "打造中国服务品牌是推动高水平对外开放的重点"
    },
    "answer": "ABC",
    "analysis": "选A、B、C。材料给数：服务业对经济增长贡献率达61.4%，撑起大半壁江山，表明服务业是经济增长的主动力。材料给数：服务业就业近3.6亿，居三次产业首位，表明服务业是吸纳就业的主渠道。部署明确要提高现代服务业与先进制造业、现代农业融合发展水平，表明生产性服务业能赋能产业升级。\n钩子：服务业三判断——增长主动力（贡献率61.4%）、就业主渠道（3.6亿）、生产性服务业赋能产业升级；品牌和对外开放重点别硬挂。\nD错在{{打造中国服务品牌是推动高水平对外开放}}：张冠李戴。打造服务品牌是为了服务业自身做强，材料没把它定位成“推动高水平对外开放的重点”，过度引申。"
