    "number": 161,
    "type": "single",
    "stem": "2022年以来，我国人口发展已经进入减量阶段，同时进入以65岁及以上人口占比超过14%为标志的中度老龄化社会。2026年2月9日至10日，习近平在北京考察并看望慰问基层干部群众时的讲话时指出：“党中央对“一老一小”格外关切，‘老’是我们的财富，人口平均预期寿命稳步提高是我们社会主义制度优越性的体现，爱老助老是全社会共同责任；小’是我们的未来，要让他们健康成长，德智体美劳全面发展。这说明完善人口发展战略，健全义全人群、全生命周期的人口服务体系，促进人口高质量发展的重点是()",
