    "type": "single",
    "stem": "鸦片战争以后，由于西方列强入侵和封建统治腐败，中国逐步成为半殖民地半封建社会，国家蒙辱、人民蒙难、文明蒙尘，中华民族遭受了前所未有的劫难。从那时起，中国社会发生两个根本变化：一是独立的中国逐步变成半殖民地的中国，二是封建的中国逐步变成半封建的中国。这种半殖民地半封建社会，是近代以来中国在外国资本-帝国主义势力入侵及其与中国封建主义势力相结合条件下，逐步形成的一种畸形社会形态。它从属于()",
