    "type": "single",
    "stem": "法安天下，德润人心。社会主义核心价值观体现国家价值目标、社会价值取向和公民价值准则。把社会主义核心价值观融入法治建设，是坚持依法治国和以德治国相结合的必然要求，是加强社会主义核心价值观建设的重要途径。之所以把社会主义核心价值观融入法治建设，是因为社会主义核心价值观是（）",
