    "stem": "纵观道德发展的历史，进步与落后、善良与邪恶、顺利与曲折交织其中，使得数千年来的道德现象纷繁复杂、矛盾重重。迄今为止，人类社会先后经历了五种基本社会形态，与此相适应，出现了原始社会的道德、奴隶社会的道德、封建社会的道德、资本主义社会的道德、社会主义社会的道德。与以往社会的道德形态相比，社会主义道德具有显著的先进性特征，主要体现在",
