    "stem": "传统道德是一个矛盾体，具有鲜明的两重性。属于精华的部分，表现出积极、革新、进步的一面;属于糟粕的部分，则表现出消极、保守、落后的一面。中华传统美德作为中国传统道德的精华部分，为今天的道德建设提供了丰富的资源。弘扬中华传统美德，必须（）",
