    "type": "multiple",
    "stem": "法律权利的行使必须伴随着法律义务的履行，法律义务更需要由法律加以规定。有义务就意味着责任，公民、法人未能依法履行义务的，根据情节轻重，应当承担相应的法律责任。法律责任主要包括（）",
