    "analysis": "选A、B、C。三类法律责任。民事责任是平等主体间违反民事义务承担的责任，是三大法律责任之一。三类法律责任。刑事责任是犯罪行为承担的最严厉责任，由刑法规定。三类法律责任。行政责任是违反行政法律规范承担的责任，是三大法律责任之一。\n钩子：法律责任三类＝民、刑、行；没有\"司法责任\"这一项，它是司法机关自己的事。\nD错在{{司法责任}}：概念偷换。\"司法责任\"指司法机关履职中的责任，不是公民、法人违法承担的法律责任类型，属于把主体偷换。"
