    "category": "政治错题",
    "number": 237,
    "type": "multiple",
    "stem": "(2024-30)中华传统美德蕴含着丰富的思想道德资源，对于我们今天的道德建设具有重要价值。习近平总书记指出:“要继承和弘扬我国人民在长期实践中培养和形成的传统美德，坚持马克思主义道德观、坚持社会主义道德观，在去粗取精、去伪存真的基础上，坚持古为今用、推陈出新，努力实现中华传统美德的创造性转化、创新性发展。”中华传统美德的“创造性转化、创新性发展”体现为",
