    "answer": "AC",
    "analysis": "选A、C。积善成德。破窗定律讲小破损会引发大破坏，反过来小善也会积成大德，\"善不可谓小而无益\"正讲小善小恶都不可轻。积善成德。\"小善不可不为、细恶不可不去\"与破窗定律完全同向：小恶不纠就会加速破损，小善要日积月累。\n钩子：破窗定律＝积善成德、防微杜渐；选讲\"小善小恶\"的句子，不选讲知难行难、见贤思齐的。\nB错在{{非知之难，行之惟难;非行之难}}：张冠李戴。这句讲知易行难、行难终更难，强调坚持到底，与\"小—大\"的积渐逻辑不是一回事。\nD错在{{见贤思齐焉，见不贤而内自省也}}：张冠李戴。\"见贤思齐、见不贤内自省\"讲的是向榜样学习、对照反省，不是积善防渐的修养方法。"
