    "answer": "C",
    "analysis": "选C。四德着力点。《新时代公民道德建设实施纲要》明确把社会公德、职业道德、家庭美德、个人品德建设作为着力点，这是教材原话。\n钩子：公民道德建设着力点＝四德（社会公德、职业道德、家庭美德、个人品德）；2019纲要固定表述。\nA错在{{弘扬民族精神和时代精神}}：张冠李戴。弘扬民族精神和时代精神是道德建设的重要任务，但不是\"四德\"这个着力点。\nB错在{{推动理想信念教育常态化制度化}}：张冠李戴。理想信念教育常态化制度化是思想建设的要求，与公民道德建设的四德着力点不是同一条。\nD错在{{传承孝老爱亲、扶危济困}}：范围/程度错。孝老爱亲、扶危济困等是具体美德条目，是家庭美德等的素材，够不上\"着力点\"这一层总概括。"
