    "number": 244,
    "type": "multiple",
    "stem": "近期，一些网络“小作文”主打“控诉”“爆料”，在社交平台扩散极快，干扰正常的公共讨论秩序。这类内容本质上是现实利益矛盾与个体情绪在互联网空间的投射，叙事曲折、主观色彩鲜明，事实细节往往难以求证。它不仅真假难辨、滋生戾气、侵蚀社会信任，更自带“舆论审判”基因：信息一经发布，被指控者名誉即遭重创，维权救济之路却艰难漫长，法治精神与公共理性遭到消解。遏制这一乱象，绝不能仅靠道德呼吁，必须将法治思维和法治方式贯穿于管网治网全过程，使虚构事实、恶意引流、操纵舆论者依法受到处置；同时强化穿透式监管、压实平台责任，自媒体和网络大V自觉校准讨论基调；个人也应提升媒介素养，审慎交叉验证信息，善用法律武器维护自身合法权益。整治网络“小作文”乱象，必须()",
