    "stem": "习近平主席有一个形象的比喻：“大家仔细看一看‘家’和‘冢’这两个字，它们很像，区别就在于那个‘点’摆在什么位置。这就像家庭建设一样，对家属子女要求高一点才能成为幸福之家，低一点就可能葬送一个好家庭。”这说明不论时代发生多大变化，生活格局发生多大变化，都要重视家庭建设，注重家庭、家教、家风。这是因为()",
