    "number": 247,
    "type": "single",
    "stem": "2026年8月15日，《中华人民共和国生态环境法典》正式施行。为推动生态环境法典高质量实施，各部门协同发力。全国人大常委会办公厅给有关方面发函，要求开展生态环境法典涉及的规范性文件集中清理工作；国务院对涉及的行政法规进行了清理，决定对12部行政法规的部分条款予以修改，对3部行政法规予以废止；生态环境部开展相关文件清理和制修订，对176件规范性文件予以废止；最高法发布法典施行后的首个配套司法解释，与法典同步施行；中央宣传部、中央组织部等19家部门和单位联合印发通知部署开展生态环境法典学习宣传工作。这说明()",
