    "type": "multiple",
    "stem": "105.发生在18世纪70年代以蒸汽机的发明为主要标志的科技革命，推动西欧国家相继完成了第一次产业革命，使 资本主义生产迅速过渡到机器大工业，为资本主义生产方式的确立奠定了物质基础。发生在19世纪末20世纪初以电力的广泛运用 为标志的科技革命，使电力取代蒸汽机成为新的动力，社会生产力又一次得到迅猛发展。20世纪中期以后出现的以原子能的利用 、电子计算机和空间技术的发展，特别是以信息技术、新材料、新能源、生物工程、海洋工程等高科技的出现为主要标志的科技 革命，使人类进入了互联网、智能化、数字化的时代，推动了由工业经济形态向信息社会或知识经济形态的过渡。当今时代，数 字技术作为世界科技革命和产业变革的先导力量，日益融入经济社会发展各领域全过程。这说明科技革命：（2分）",
