    "answer": "CD",
    "analysis": "选C、D。“世界上唯一不变的是变化本身”正是说运动是绝对的、静止是相对的，变不会停，不变只是暂时的。变和不变又辩证地统一在一起，没有离开变的不变，也没有离开不变的变。\n钩子：本原＝物质；运动绝对、静止相对；只讲“只有变”是相对主义诡辩。\nA错在{{变是世界的本原}}：概念偷换。世界的本原是物质，变是物质的存在方式，不是本原。\nB错在{{世界上只有变，没有不变}}：范围/程度错。相对静止是存在的，不是只有变、没有任何稳定的时候。"
