    "stem": "太阳是离地球最近的恒星，其剧烈活动深刻影响地球环境与高技术系统。中华民族自古便观测记录太阳活动， 积累了丰富天象知识。新中国成立后，太阳物理研究持续发展，为保障航天活动、参与国际合作奠定了基础。当下，国际太阳研 究不断提速。“帕克太阳探针”探测到太阳风中的“磁岛”结构、“磁偏折”现象和大量微纳耀斑;“太阳轨道器”进入水星轨 道以内，获取太阳风等离子体和磁场的源头信息;人类正在发起一场新的“哥白尼式”天文学革命，揭示太阳、恒星周边世界和 生命起源的奥秘。近年来，中国“羲和号”“夸父一号”相继发射，进入空间探日新时代，并着手研制太阳极轨天文台，以揭示 太阳极区对空间天气的关键影响，旨在为全球太阳观测体系贡献中国力量。这一材料表明：（2分）",
