    "stem": "屠呦呦是新中国培养的第一代药学家。1969年1月，屠呦呦接手了一个全国性大协作项目——“523”任务，它涵 盖了疟疾防控的所有领域。葛洪的《肘后备急方》中关于青蒿抗疟的记载，给了课题组灵感——“青蒿一握，以水二升渍，绞取 汁，尽服之。”屠呦呦用沸点只有34.6℃的乙醚来提取青蒿，但这一实验过程繁复而冗长。1971年10月4日，在190次失败后，191 号青蒿乙醚中性提取物样品抗疟实验的最后结果出炉——对疟原虫的抑制率达到100%。屠呦呦在被授予“共和国勋章”后说:“ 我最大的梦想就是用古老的中医药，促进人类健康，让全世界的人们都能分享到它的好处。”这一事实说明：（2分）",
