    "type": "multiple",
    "stem": "马克思在《资本论》中指出:“生产资料的集中和劳动的社会化，达到了同它们的资本主义外壳不能相容的地步 。这个外壳就要炸毁了。资本主义私有制的丧钟就要响了。剥夺者就要被剥夺了。”这说明资本主义生产关系不再适应生产力状 况时，公有制取代私有制、社会主义取代资本主义就将成为不可避免的结果。这是资本积累过程所具有的客观历史趋势。因为资 本的不断积累：（2分）",
