    "stem": "南北朝时期著名诗人王籍的作品《入若耶溪》中有两句脍炙人口的诗句:\"蝉噪林逾静，鸟鸣山更幽。\"它的绝妙 之处是用以动显静的手法来渲染山林的幽静。蝉的声音更体现出了树林的幽静，鸟的鸣叫更衬托出了山的空寂。下列诗句中蕴含 相同哲理的是：（2分）",
