    "category": "政治错题",
    "number": 406,
    "type": "multiple",
    "stem": "随着温室气体排放量增加，全球海洋正加速变暖。自2005年以来，其变暖速率翻了近一番，从0.58瓦特每平方米 增至1.05瓦特每平方米。越来越多的研究指出，海洋变暖不仅会影响海洋及其中的生物，还会对地球气候系统产生影响，催生和 加剧全球更频、更强的极端天气。海洋变暖还导致冰川和冰盖加速融化，海平面不断上升，使得(超)强台风一风暴潮增水更易形 成灾害性水位，加剧洪涝灾害程度。赤道中东太平洋海表温度升高，形成厄尔尼诺事件，会引发全球或区域极端事件，如巴西干 旱、澳大利亚高温热浪和森林野火等一系列气候异常。这一现象表明：（2分）",
