    "analysis": "选A、B、D。生产价格原理。单个部门平均利润可高于或低于本部门剩余价值，但全社会平均利润总额仍等于剩余价值总额，所以按生产价格卖不违背价值规律。生产价格原理。全社会生产价格总额等于商品价值总额，整个社会看，价格围绕的还是价值，只是实现形式变了。生产价格原理。价值变了，生产价格跟着变，生产价格的变动归根到底由商品价值变动决定，价值仍是基础。\n钩子：生产价格＝成本＋平均利润；全社会利润总额＝剩余价值总额，生产价格总额＝价值总额，价值没被取代。\nC错在{{生产价格取代价值成为决定商品交换比例}}：概念偷换。生产价格只是价值的转化形式，价值并没有退场；说生产价格\"取代\"价值，把转化关系说成替代关系了。"
