    "stem": "自从中国产生了共产党，中国人民就开始从精神上由被动转为主动，一切奋斗和创造就有了主心骨。100多年来 ，从被动挨打、饱受欺凌到独立自主、坚定自信，中国人民成为国家、社会和自己命运的主人，创造了\"两大奇迹\",在新时代焕发 出更为强烈的主动精神，书写着当代中国发展的伟大历史。从被动到主动，再到前所未有的历史自觉和历史主动，中国人民的面 貌焕然一新，神州大地沧海桑田。\"中国的今天正在亿万人民手中创造，中国的明天必将更加美好。\"这从社会更替的必然性与人 们的历史选择性角度证明了( )：（2分）",
