    "analysis": "选A、B、D。物质范畴。暗物质不发光、电磁波摸不着，照样不依赖人的意识存在；把客观实在性缩成看得见摸得着的实物，就错了。物质范畴。客观实在性是物质的唯一共同特性，不管能不能直接感知都具有；这观点不承认这一点，把能不能感知当标准。物质范畴。暗物质、电磁波不能直接感知，却是客观实在；这观点把客观实在性局限在可直接感知的宏观物体里，缩小了物质范围。\n钩子：客观实在性＝物质唯一共同特性，跟能不能感知无关；不能直接感知不等于没有客观实在性。\nC错在{{否认物质是人类感官可以直接感知的存在}}：张冠李戴。题干并没有否认物质能被感官感知，它的错误是把\"能不能直接感知\"当成\"有没有客观实在性\"的标准，不是否认物质可感知。"
