    "type": "multiple",
    "stem": "【阅读理解】\"比较复杂的劳动只是自乘的或不如说多倍的简单劳动，因此，少量的复杂劳动等于多量的简单劳 动。各种劳动化为当作它们的计量单位的简单劳动的不同比例，是在生产者背后由社会过程决定的，因而在他们看来，似乎是由 习惯确定的。\"这段论述表明：（2分）",
