    "analysis": "选A、C。利润平均化。有机构成高的部门可以通过平均利润拿走别的部门工人创造的剩余价值，所以某企业工人创造的剩余价值有被其他资本家侵占的可能。资本家阶级共同利益。全社会资本家分的是同一块剩余价值蛋糕，所以在加紧剥削工人阶级上，他们有共同的阶级利益。\n钩子：利润平均化＝部门间瓜分剩余价值；同部门内仍有超额利润；银行资本家也参与平均利润。\nB错在{{各部门内不同资本家的等量投资所得到的}}：概念偷换。利润平均化发生在不同部门之间，不是同一部门内；同一部门里技术领先的企业仍能拿到超额利润。\nD错在{{不从事直接生产的银行资本家所获得的利}}：范围/程度错。银行资本同样参与利润平均化，获得平均利润；说\"总是低于\"不对，\"总是\"把它说死了。"
