    "stem": "【阅读理解】2025年12月10日，国际研究团队在《科学进展》杂志发表研究成果，宣布通过分析潮汐瓦解事件A T2020afhd,首次直接观测到旋转黑洞拖拽周围时空，导致其吸积盘与喷流以约20天为周期协同摆动的现象。该发现直接印证了爱 因斯坦广义相对论预言的\"参考系拖曳效应\",揭示了黑洞极端引力场中时空与物质的深刻关联。这一成果不仅再次验证了经典理论 ，更为研究黑洞自转、喷流形成等宇宙本质问题开辟了新途径。该科学突破表明：（2分）",
