    "stem": "中国共产党团结带领中国人民追求民族复兴的历史，也是一部不断探索现代化道路的历史。在新中国成立特别是 改革开放以来长期探索和实践基础上，经过党的十八大以来在理论和实践上的创新突破，我们成功推进和拓展了中国式现代化。 中国式现代化()：（1分）",
