    "stem": "党的二十届三中全会，通过的《中共中央关于进一步全面深化改革、推进中国式现代化的决定》,明确了进一步 全面深化改革的总目标，既是十八届三中全会以来全面深化改革的实践续篇，也是新征程推进中国式现代化的时代新篇，开启了 ()：（1分）",
