    "type": "single",
    "stem": "全面深化改革开放，是新时代坚持和发展中国特色社会主义的根本动力。进一步全面深化改革，为中国式现代化 提供强大动力和制度保障。为全面深化改革提供强大力量源泉的是()：（1分）",
    "options": {
      "A": "坚持党的全面领导",
      "B": "坚持守正创新",
      "C": "坚持以人民为中心",
      "D": "坚持系统观念"
    },
