    "stem": "在党的七届二中全会上，毛泽东将“国家和私人合作的国家资本主义经济”作为新中国的几种主要的经济成分 之一。在新中国社会主义改造过程中，中国共产党采用国家资本主义的方式开展对资本主义工商业的社会主义改造，即通过在一 定的时期内有步骤地、有区别地把一切对国计民生有利的、而又为国家所需要的资本主义企业基本上改造为国家资本主义企业， 并有计划地稳步地使低级形式的国家资本主义向高级形式的国家资本主义发展。国家资本主义：（2分）",
