    "analysis": "选A、C、D。政治思想领域处理人民内部矛盾，从团结的愿望出发，经过批评或者斗争使矛盾得到解决，从而在新的基础上达到新的团结，即团结—批评—团结。科学文化领域不能用行政力量强制推行一种学派、压制另一种，要实行百花齐放、百家争鸣，通过艺术和科学的自由讨论解决矛盾。处理民族之间的矛盾，实行民族平等、团结互助，各民族不分大小一律平等，共同发展，反对大汉族主义和地方民族主义。\n钩子：人民内部矛盾分领域四方针——政治思想上团结批评团结、物质利益上统筹兼顾适当安排、科学文化上双百、民族上平等团结互助。\nB错在{{在物质利益、分配方面}}：概念偷换。物质利益和分配方面的方针是\"统筹兼顾、适当安排\"，不是\"按劳分配与适当兼顾相结合\"，原话被改了字，意思就变了。"
