    "category": "政治错题",
    "number": 633,
    "type": "multiple",
    "stem": "毛泽东同志在《关于正确处理人民内部矛盾的问题》中指出，社会主义社会具有两类不同性质的矛盾。敌我矛盾 是对抗性的矛盾，人民内部矛盾是在人民根本利益一致基础上的矛盾，因而是非对抗性的矛盾。处理人民内部矛盾要采取民主的 方法，这一方法是()：（2分）",
