    "analysis": "选A、C、D。调动一切积极因素，首要前提是坚持党的领导，没有党的领导就没有统一意志，积极因素调动不起来，对应材料\"基本方针\"的落实。调动一切积极因素，要发展社会主义民主政治，让党外人士、各方面意见都能进来，对应材料\"党内党外、国内国外\"。积极因素和消极因素不是死的，在一定条件下可以互相转化，要创造条件把消极因素转化成积极因素，这是辩证法。\n钩子：调动积极因素三要点——党的领导+发展民主+积极消极可转化；别信\"消极因素已消除\"这种绝对化表述。\nB错在{{必须看到社会主义建设已消除了消极因素}}：范围/程度错。说\"已消除了消极因素\"不对，消极因素并没有消除，客观存在；任务是调动积极因素，同时化消极因素为积极因素。"
