    "analysis": "选A、B。马克思主义要在中国管用，就得解决中国的实际问题，离开中国实际就是空洞的教条，材料引\"离开中国特色就是空洞的马克思主义\"直接对应。马克思主义不是教条而是行动指南，它本身要求在实践中不断丰富发展，这是理论发展的内在要求，对应材料\"伟大力量在于和具体实践相联系\"。\n钩子：推进马克思主义中国化时代化两原因——解决中国实际问题的需要+理论本身发展的内在要求；不是\"自然而然\"，是中国化包含时代化。\nC错在{{马克思主义能够自然而然地解决中国革命}}：范围/程度错。马克思主义不会\"自然而然\"解决中国问题，必须经过\"两个结合\"、跟中国实际和国情结合才行；说自动解决是懒汉思想。\nD错在{{马克思主义时代化同时包含着马克思主义}}：概念偷换。说反了，是马克思主义中国化同时包含着时代化的意蕴，不是\"时代化包含中国化\"，两者包含关系别搞反。"
