    "number": 687,
    "type": "multiple",
    "stem": "毛泽东在《新民主主义论》中指出:\"既然中国社会还是一个殖民地、半殖民地、半封建的社会，既然中国革命的 敌人主要的还是帝国主义和封建势力，既然中国革命的任务是为了推翻这两个主要敌人的民族革命和民主革命;而推翻这两个敌 人的革命，有时还有资产阶级参加，即使大资产阶级背叛革命而成了革命的敌人，革命的锋芒也不是向着一般的资本主义和资本 主义的私有财产，而是向着帝国主义和封建主义。\"这说明决定了中国革命的性质是资产阶级民主主义革命的是( )：（2分）",
