    "type": "single",
    "stem": "【阅读理解】中国的新民主主义革命实质上就是无产阶级领导下的农民革命。中国革命的一些基本理论和实践 问题都与农民问题紧密地联系着。这一论断表明：（1分）",
    "options": {
      "A": "农民阶级是中国革命最基本的动力",
      "B": "无产阶级对革命领导权主要通过对农民的领导来实现",
      "C": "农民问题是中国革命的根本保证",
      "D": "无产阶级和农民阶级在革命性质上具有同一性"
    },
    "answer": "B",
    "analysis": "选B。中国革命实质上是无产阶级领导下的农民革命，无产阶级要实现领导权，主要靠把农民这个最广大同盟军领起来，对应材料\"实质上就是无产阶级领导下的农民革命\"。\n钩子：农民=主力军、无产阶级=最基本动力、党的领导=根本保证、领导权主要通过领导农民实现；别把这几个定位互换。\nA错在{{农民阶级是中国革命最基本的动力}}：概念偷换。中国革命最基本的动力是无产阶级，农民是主力军；把\"最基本动力\"安到农民头上，搞混了动力和主力军。\nC错在{{农民问题是中国革命的根本保证}}：概念偷换。中国革命的根本保证是党的领导，农民问题是革命的基本问题；说农民问题是\"根本保证\"定位错了。\nD错在{{无产阶级和农民阶级在革命性质上具有同}}：概念偷换。无产阶级是领导阶级，农民是同盟军，两者在革命性质上并不相同，谈不上\"同一性\"；领导和被领导不是同一。"
