    "type": "multiple",
    "stem": "【基础素养】1992年，邓小平在南方谈话中明确指出:\"计划多一点还是市场多一点，不是社会主义与资本主义的 本质区别。计划经济不等于社会主义，资本主义也有计划;市场经济不等于资本主义，社会主义也有市场。计划和市场都是经济 手段。\"这一精辟论述：（2分）",
