    "stem": "党的十三大报告提出党在社会主义初级阶段的基本路线是:领导和团结全国各族人民，以经济建设为中心，坚持 四项基本原则，坚持改革开放，自力更生，艰苦创业，为把我国建设成为富强、民主、文明的社会主义现代化国家而奋斗。其中 ，以经济建设为中心（ ）：（2分）",
