    "analysis": "选A、B、C、D。新民主主义革命是资产阶级民主主义革命，社会主义革命是无产阶级革命，革命性质根本不同，这是最根本区别。新民主主义革命联合并保护民族工商业、民族资产阶级；社会主义革命要把资本主义工商业改造掉、消灭剥削，政策不一样。新民主主义革命对象是帝国主义、封建主义、官僚资本主义；社会主义革命对象是资本主义和资产阶级，对象不同。新民主主义革命建立各革命阶级联合专政，社会主义革命后建立无产阶级专政（人民民主专政），政权性质不同。\n钩子：两场革命四不同——性质不同+对民族资产阶级政策不同+对象不同+政权性质不同；新民主主义是民主革命，社会主义革命是消灭资本主义。"
