    "answer": "BD",
    "analysis": "选B、D。《临时约法》以根本大法形式废除了两千多年的封建君主专制制度，这是它革命性的最大体现。它规定“中华民国之主权属于国民全体”，确立了资产阶级共和国的政治制度，这是民主性的核心条款。\n钩子：临时约法的革命性民主性=根本大法废君主专制+主权属国民全体；民主集中制、没收土地都不在其中。\nA错在{{规定各级政权机关一律实行民主集中制}}：张冠李戴。民主集中制是后来人民政权的组织原则，《临时约法》规定的是责任内阁制等资产阶级代议制，不是民主集中制。\nC错在{{消灭了封建土地制度}}：范围/程度错。《临时约法》是资产阶级宪法性质文件，没有也不可能消灭封建土地制度、没收地主土地财产。"
