    "stem": "1917年俄国爆发的十月社会主义革命，是一个具有划时代意义的世界性的历史事件。十月革命的胜利开创人类历 史的新纪元，为世界各国无产阶级革命、殖民地和半殖民地的民族解放运动开辟胜利前进的道路。十月革命启示中国先进分子() ：（2分）",
