    "analysis": "选A、C。游击战被提到战略地位，首先在于它主要是在敌后外线单独作战，不是在内线给正规军当配角。中国是大国又是民族战争，游击战能大规模开展，这是它具备战略全局性的第二个原因。\n钩子：游击战上战略地位两原因——外线单独作战、大规模；不是主要作战方式、不是只进攻。\nB错在{{是抗日战争的主要作战方式}}：范围/程度错。有战略地位不等于它就是抗战主要作战方式，就全国而言，正规战仍占主要地位。\nD错在{{是进攻战，而不是防御战}}：概念偷换。游击战的战略地位来自外线单独作战和大规模，并非因为它只进攻、不防御，它本身就有防御性质。"
