    "answer": "ABC",
    "analysis": "选A、B、C。农民占近代中国人口绝大多数，受地主残酷剥削，是民主革命主力军，但小生产者的局限决定了它不能独立领导革命取得胜利。工人阶级身受帝国主义、封建主义、资本主义三重压迫，革命性最坚决，又有组织纪律性和与农民的天然联系，是领导阶级。民族资产阶级受帝国主义和封建主义压迫有革命性，但经济上软弱又跟帝国主义封建主义有千丝万缕联系，有妥协性，领导不了彻底胜利。\n钩子：近代中国三阶级特点＝农民主力但领导不了＋工人最革命＋资产阶级两面性；地主转化后阶级更复杂，不是更单一。\nD错在{{地主阶级中的一部分投资于近代工商业}}：范围/程度错。地主一部分投资工商业后往往一身兼地主和资本家，阶级关系更复杂了，不是\"趋于单一\"。"
