    "type": "multiple",
    "stem": "1956年9月15日至27日，中国共产党第八次全国代表大会在北京举行。毛泽东致开幕词，刘少奇作政治报告，周 恩来作关于发展国民经济第二个五年计划建议的报告，邓小平作关于修改党章的报告。中共八大的路线是正确的，提出的许多新 方针和新设想是富于创造精神的。中共八大：（2分）",
