    "analysis": "选A、B、C。早期组织成立后第一件事就是研究和宣传马克思主义，同时研究中国实际问题，为建党做理论准备。早期组织深入工人群众中去办夜校、工会，宣传马克思主义，把工人阶级组织起来，这是重要工作。各地早期组织还就建党问题展开讨论，并实际开展组织工作，为一大召开做了直接准备。\n钩子：早期组织三工作＝研究宣传马义＋到工人中宣传组织＋讨论建党；集中精力组织工人是一大定的中心任务。\nD错在{{集中精力组织工人}}：张冠李戴。集中精力组织工人是中共一大确定的中心任务，不是早期组织这一段的主要工作内容。"
