    "analysis": "选A、B、D。二大最低纲领之一：统一中国本部（包括东三省）为真正民主共和国，这是民主革命要达到的目标。二大最低纲领：消除内乱、打倒军阀、建设国内和平，矛头直指封建军阀统治。二大最低纲领：推翻国际帝国主义的压迫，达到中华民族完全独立，这是反帝的明确表述。\n钩子：二大民主革命纲领（最低纲领）＝打倒军阀＋推翻帝国主义＋统一为真正民主共和国；劳农专政铲私有制是最高纲领。\nC错在{{建立劳农专政的政治，铲除私有财产制度}}：张冠李戴。建立劳农专政、铲除私有财产制度是二大最高纲领即实现社会主义的内容，不是现阶段民主革命纲领。"
