    "number": 877,
    "type": "multiple",
    "stem": "王继才生前是江苏省灌云县开山岛民兵哨所所长。1986年，26岁的王继才接受了守岛任务，从此与妻子以海岛为 家，与孤独相伴，在没水没电、植物都难以存活的孤岛上默默坚守，把青春年华全部献给了祖国的海防事业。2014年，王继才夫 妇被评为全国“时代楷模”。2018年7月27日，王继才在执勤时突发疾病，经抢救无效去世，年仅58岁。习近平总书记对王继才 同志先进事迹作出重要指示强调，要大力倡导这种爱国奉献精神，使之成为新时代奋斗者的价值追求。以下说法正确的有：",
