    "analysis": "选A、C、D。社会经济权利。劳动权和休息权是社会经济权利的核心，国家保障人有活干、有假休。社会经济权利。社会保障权是社会经济权利，国家在年老疾病失业时提供保障。社会经济权利。物质帮助权也是社会经济权利，公民在困难时从国家获得帮助。\n钩子：社会经济权利＝劳动权、休息权、社会保障权、物质帮助权；私有财产权属财产权，别串。\nB错在{{私有财产权}}：张冠李戴。私有财产权和继承权属于财产权利，不是社会经济权利，帽子戴错。"
