    "type": "single",
    "stem": "【基础素养】社会主义核心价值观的基本内容是富强、民主、文明、和谐，自由、平等、公正、法治，爱国、敬 业、诚信、友善。其中，既是社会进步的重要标志，也是社会主义现代化国家的重要特征的是：",
